CREATE DATABASE IF NOT EXISTS credit_ads CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE credit_ads;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,credits INT UNSIGNED NOT NULL DEFAULT 0,is_admin TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE ads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,ad_text VARCHAR(40) NOT NULL,url VARCHAR(2048) NOT NULL,ad_type ENUM('framed','frameless') NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',rejection_reason VARCHAR(500) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_at TIMESTAMP NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(status),INDEX(user_id)) ENGINE=InnoDB;
CREATE TABLE ad_views (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ad_id BIGINT UNSIGNED NOT NULL,viewer_id BIGINT UNSIGNED NOT NULL,session_token CHAR(64) NOT NULL UNIQUE,started_at DATETIME NOT NULL,completed_at DATETIME NULL,seconds_viewed INT UNSIGNED NOT NULL DEFAULT 0,credits_awarded TINYINT(1) NOT NULL DEFAULT 0,FOREIGN KEY(ad_id) REFERENCES ads(id) ON DELETE CASCADE,FOREIGN KEY(viewer_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(viewer_id,ad_id)) ENGINE=InnoDB;
CREATE TABLE credit_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,amount INT NOT NULL,type VARCHAR(40) NOT NULL,reference_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)) ENGINE=InnoDB;
